//RC pass and change
//History:
//original:https://www.shadertoy.com/view/X33BzN
//fork1 (this sketch): https://www.shadertoy.com/view/XXdBWl
float TAU = 6.28318;

// Cycle through a color palette with a cosine wave
vec3 palette( float t ) {
    vec3 offset = vec3(0.3, 0.4, 0.2);
    vec3 amplitude = vec3(0.1, 0.1, 0.2);
    vec3 frequency = vec3(1.0, 1.0, 1.0);
    vec3 phase = vec3(0.263, 0.416, 0.557);

    return offset + amplitude * cos(TAU * (frequency * t + phase));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     // Normalized pixel coordinates (from -1 to 1)
    // (-1,-1) = bottom left corner
    // (1,1) = top right corner
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;

    // Default background color changes with time
    vec3 color = palette(0.1 * iTime);

    // Sine wave based on y coordinate
    if (uv.x < sin(uv.y + iTime)) {
        // Offset iTime so the color is different
        color = palette(iTime * 0.1 + 0.5);
    }

    // Sine wave based on x coordinate
    if (uv.y < sin(uv.x + iTime)) {
        // Offset iTime by a different amount
        color = palette(iTime * 0.1 + 0.2);
    }
    //lava circle thing:
    //compute distance from center (0, 0)
    float distFromCenter = length(uv)*abs(cos(iTime*0.1+uv.x*uv.y));

    //radius for annulus
    float radius = 0.3 +0.1*sin(iTime*0.3);  
    float radius2 = 0.25 +0.1*sin(iTime*0.3); 

    //if the fragment is within threshold(radius and radius2) bounds - invert the color
    if (distFromCenter < radius && distFromCenter > radius2) {
    //color inversion
        color = 1.0 - color;  
    }
    // -------------------------------------------------------------------

    // Output with an alpha of 1
    fragColor = vec4(color, 1);
}
